def chg_class(v):
    if v is None: return "chg-flat"
    if v > 0: return "chg-up"
    if v < 0: return "chg-down"
    return "chg-flat"

def chg_str(v, suffix="%", decimals=1):
    if v is None: return "—"
    sign = "+" if v > 0 else ""
    return f"{sign}{v:.{decimals}f}{suffix}"

def attr_badge(media_pct, creative_pct):
    if media_pct >= 60:
        return '<span class="attr-badge attr-media">媒体侧主导</span>'
    elif creative_pct >= 60:
        return '<span class="attr-badge attr-creative">创意侧主导</span>'
    else:
        return '<span class="attr-badge attr-both">媒体+创意共同</span>'

def type_tag(t):
    tags = {
        "media":    '<span class="tag tag-warn">媒体侧CPM↑</span>',
        "creative": '<span class="tag tag-warn">创意侧IPM↓</span>',
        "both":     '<span class="tag tag-warn">CPM↑+IPM↓</span>',
        "media_down":    '<span class="tag tag-ok">媒体侧CPM↓</span>',
        "creative_down": '<span class="tag tag-ok">创意侧IPM↑</span>',
        "both_down":     '<span class="tag tag-ok">CPM↓+IPM↑</span>',
        "ok":       '<span class="tag tag-ok">正常/改善</span>',
    }
    return tags.get(t, "")

def render_publishers(pubs):
    if not pubs:
        return '<div class="pending-msg">📊 Publisher 数据待查（下次更新补充）</div>'
    rows = ""
    for p in pubs:
        share_chg = p.get("share_chg")
        share_cls = "share-up" if (share_chg or 0) > 1 else ("share-down" if (share_chg or 0) < -1 else "chg-flat")
        share_str = chg_str(share_chg, suffix="pp") if share_chg else "—"
        rows += f"""
        <tr>
          <td class="name-cell" title="{p['name']}">{p['name'][:35]}{'…' if len(p['name'])>35 else ''}</td>
          <td>{p.get('prev_share', 0):.1f}%</td>
          <td>{p.get('curr_share', 0):.1f}%</td>
          <td class="{share_cls}">{share_str}</td>
          <td class="{chg_class(p.get('cpi_chg'))}">{chg_str(p.get('cpi_chg'))}</td>
          <td class="{chg_class(p.get('cpm_chg'))}">{chg_str(p.get('cpm_chg'))}</td>
          <td class="{chg_class(p.get('ipm_chg'))}">{chg_str(p.get('ipm_chg'))}</td>
          <td>{type_tag(p.get('type','ok'))}</td>
        </tr>"""
    return f"""
    <div class="table-title"><span class="icon icon-pub">P</span>Top Publishers 明细（媒体侧）</div>
    <table>
      <tr><th>Publisher</th><th>上期占比</th><th>本期占比</th><th>占比变化</th>
          <th>CPI 变化</th><th>CPM 变化</th><th>IPM 变化</th><th>类型</th></tr>
      {rows}
    </table>"""

def render_formats(fmts):
    if not fmts:
        return '<div class="pending-msg">🎨 Creative Format 数据待查（下次更新补充）</div>'
    rows = ""
    for f in fmts:
        share_chg = f.get("share_chg")
        share_cls = "share-up" if (share_chg or 0) > 1 else ("share-down" if (share_chg or 0) < -1 else "chg-flat")
        share_str = chg_str(share_chg, suffix="pp") if share_chg else "—"
        rows += f"""
        <tr>
          <td><span class="fmt-badge">{f['name']}</span></td>
          <td>{f.get('prev_share', 0):.1f}%</td>
          <td>{f.get('curr_share', 0):.1f}%</td>
          <td class="{share_cls}">{share_str}</td>
          <td class="{chg_class(f.get('cpi_chg'))}">{chg_str(f.get('cpi_chg'))}</td>
          <td class="{chg_class(f.get('ipm_chg'))}">{chg_str(f.get('ipm_chg'))}</td>
          <td class="{chg_class(f.get('ctr_chg'))}">{chg_str(f.get('ctr_chg'), suffix='pp')}</td>
          <td>{type_tag(f.get('type','ok'))}</td>
        </tr>"""
    return f"""
    <div class="table-title"><span class="icon icon-fmt">F</span>Creative Format 明细（创意侧）</div>
    <table>
      <tr><th>Format</th><th>上期占比</th><th>本期占比</th><th>占比变化</th>
          <th>CPI 变化</th><th>IPM 变化</th><th>CTR 变化</th><th>类型</th></tr>
      {rows}
    </table>"""

def render_market_benchmark(c):
    benchmarks = c.get("market_benchmarks", [])
    if not benchmarks:
        return ""
    rows = ""
    for b in benchmarks:
        gap = b.get("customer_vs_market_cpi_chg")
        if gap is None:
            gap_label = "—"
            gap_cls = "chg-flat"
            verdict = "样本不足"
        else:
            gap_label = chg_str(gap)
            gap_cls = chg_class(gap)
            if gap >= 5:
                verdict = "客户高于大盘"
            elif gap <= -5:
                verdict = "客户低于大盘"
            else:
                verdict = "接近大盘"
        prev_cpi = f"${b['prev_cpi']:.2f}" if b.get("prev_cpi") is not None else "—"
        curr_cpi = f"${b['curr_cpi']:.2f}" if b.get("curr_cpi") is not None else "—"
        rows += f"""
        <tr>
          <td>{b['market_segment']}</td>
          <td>{prev_cpi} → {curr_cpi}</td>
          <td class="{chg_class(b.get('cpi_chg'))}">{chg_str(b.get('cpi_chg'))}</td>
          <td class="{chg_class(b.get('cpm_chg'))}">{chg_str(b.get('cpm_chg'))}</td>
          <td class="{chg_class(b.get('ipm_chg'))}">{chg_str(b.get('ipm_chg'))}</td>
          <td class="{gap_cls}">{gap_label}</td>
          <td>{verdict}</td>
          <td>${b.get('curr_spend', 0):,.0f}</td>
          <td>{b.get('curr_products', 0):,}</td>
        </tr>"""
    return f"""
    <div class="benchmark-section">
      <div class="table-title"><span class="icon icon-bench">B</span>国家大盘 Benchmark（同国家/同OS，排除本报告 TikTok 账户）</div>
      <table>
        <tr><th>大盘类型</th><th>大盘 CPI</th><th>CPI变化</th><th>CPM变化</th><th>IPM变化</th>
            <th>客户 vs 大盘</th><th>状态</th><th>本期消耗</th><th>产品数</th></tr>
        {rows}
      </table>
    </div>"""

def is_country_triggered(c):
    cpi_chg = c.get("cpi_chg")
    prev_dnu = c.get("prev_dnu", 0) or 0
    curr_dnu = c.get("curr_dnu", 0) or 0
    dnu_chg = ((curr_dnu / prev_dnu - 1) * 100) if prev_dnu > 0 else None
    return (
        (cpi_chg is not None and abs(cpi_chg) >= 10)
        or (dnu_chg is not None and abs(dnu_chg) >= 10)
    )

def render_country_block(c):
    media = c["media_pct"]
    creative = c["creative_pct"]
    mbar = max(0, min(100, media))
    cbar = max(0, min(100, creative))
    if mbar + cbar > 100:
        total = mbar + cbar; mbar = int(mbar/total*100); cbar = 100-mbar

    prev_cpi_text = f"${c['prev_cpi']:.2f}" if c.get("prev_cpi") is not None else "—"
    curr_cpi_text = f"${c['curr_cpi']:.2f}" if c.get("curr_cpi") is not None else "—"
    prev_cpm_text = f"${c['prev_cpm']:.2f}" if c.get("prev_cpm") is not None else "—"
    curr_cpm_text = f"${c['curr_cpm']:.2f}" if c.get("curr_cpm") is not None else "—"
    prev_ipm_text = f"{c['prev_ipm']:.2f}" if c.get("prev_ipm") is not None else "—"
    curr_ipm_text = f"{c['curr_ipm']:.2f}" if c.get("curr_ipm") is not None else "—"

    cpi_chg = c.get("cpi_chg")
    if cpi_chg is None:
        cpi_badge_cls = "cpi-flat"
        cpi_label = "CPI 新增/无可比"
    elif cpi_chg >= 0:
        cpi_badge_cls = "cpi-up"
        cpi_label = f"CPI {chg_str(cpi_chg)}"
    else:
        cpi_badge_cls = "cpi-down"
        cpi_label = f"CPI {chg_str(cpi_chg)}"

    campaigns_html = ""
    if c.get("campaigns"):
        rows = ""
        for cam in c["campaigns"]:
            cpi_prev = f"${cam['prev_cpi']:.2f}" if cam.get("prev_cpi") else "—"
            cpi_curr = f"${cam['curr_cpi']:.2f}" if cam.get("curr_cpi") else "—"
            rows += f"""
            <tr>
              <td class="name-cell" title="{cam['name']}">{cam['name'][:40]}{'…' if len(cam['name'])>40 else ''}</td>
              <td>{cpi_prev}</td><td>{cpi_curr}</td>
              <td class="{chg_class(cam['cpi_chg'])}">{chg_str(cam['cpi_chg'])}</td>
              <td class="{chg_class(cam['cpm_chg'])}">{chg_str(cam['cpm_chg'])}</td>
              <td class="{chg_class(cam['ipm_chg'])}">{chg_str(cam['ipm_chg'])}</td>
              <td>{type_tag(cam['type'])}</td>
            </tr>"""
        campaigns_html = f"""
        <div class="table-title"><span class="icon icon-creative">C</span>Campaign 明细</div>
        <table>
          <tr><th>Campaign</th><th>Moloco CPI 上期</th><th>Moloco CPI 本期</th><th>Moloco CPI 变化</th>
              <th>CPM 变化</th><th>IPM 变化</th><th>类型</th></tr>
          {rows}
        </table>"""

    exchanges_html = ""
    if c.get("exchanges"):
        rows = ""
        for ex in c["exchanges"]:
            share_chg = ex["share_chg"]
            share_str = f"{chg_str(share_chg, suffix='pp')} {'⚠' if share_chg >= 2 else ('↓' if share_chg <= -2 else '')}" if share_chg != 0 else "—"
            share_cls = "share-up" if share_chg > 1 else ("share-down" if share_chg < -1 else "chg-flat")
            rows += f"""
            <tr>
              <td>{ex['name']}</td>
              <td>{ex['prev_share']:.1f}%</td><td>{ex['curr_share']:.1f}%</td>
              <td class="{share_cls}">{share_str}</td>
              <td class="{chg_class(ex['cpi_chg'])}">{chg_str(ex['cpi_chg'])}</td>
              <td class="{chg_class(ex['prev_cpm_chg'])}">{chg_str(ex['prev_cpm_chg'])}</td>
              <td class="{chg_class(ex['ipm_chg'])}">{chg_str(ex['ipm_chg'])}</td>
              <td>{type_tag(ex['type'])}</td>
            </tr>"""
        exchanges_html = f"""
        <div class="table-title"><span class="icon icon-media">M</span>Exchange 明细（媒体侧）</div>
        <table>
          <tr><th>Exchange</th><th>上期占比</th><th>本期占比</th><th>占比变化</th>
              <th>CPI 变化</th><th>CPM 变化</th><th>IPM 变化</th><th>类型</th></tr>
          {rows}
        </table>"""

    publishers_html = render_publishers(c.get("publishers", []))
    formats_html = render_formats(c.get("formats", []))
    benchmark_html = render_market_benchmark(c)

    ctr_row = ""
    if (
        c.get("prev_ctr") is not None
        and c.get("curr_ctr") is not None
        and c.get("prev_cvr") is not None
        and c.get("curr_cvr") is not None
    ):
        ctr_chg = c["curr_ctr"] - c["prev_ctr"]
        cvr_chg = (c["curr_cvr"] - c["prev_cvr"]) / c["prev_cvr"] * 100 if c["prev_cvr"] else 0
        ctr_row = f"""
        <div class="metric-pill"><div class="m-label">CTR</div><div class="m-val">{c['prev_ctr']:.1f}%→{c['curr_ctr']:.1f}%</div><div class="m-chg {chg_class(ctr_chg)}">{chg_str(ctr_chg, suffix='pp')}</div></div>
        <div class="metric-pill"><div class="m-label">CVR</div><div class="m-val">{c['prev_cvr']:.2f}%→{c['curr_cvr']:.2f}%</div><div class="m-chg {chg_class(cvr_chg)}">{chg_str(cvr_chg)}</div></div>"""

    return f"""
  <div class="country-block">
    <div class="country-header">
      <div class="country-name">{c['flag']} {c['name']}</div>
      <span class="cpi-badge {cpi_badge_cls}">{cpi_label}</span>
      {attr_badge(media, creative)}
      <div style="margin-left:auto;font-size:12px;color:#94a3b8;">{prev_cpi_text} → {curr_cpi_text}</div>
    </div>
    <div class="attr-section">
      <div class="attr-bar-wrap">
        <div style="font-size:11px;color:#64748b;width:56px;">归因</div>
        <div class="attr-bar">
          <div class="attr-media-fill" style="width:{mbar}%"></div>
          <div class="attr-creative-fill" style="width:{cbar}%"></div>
        </div>
        <div class="attr-labels">
          <span><span class="dot" style="background:#f97316"></span>媒体侧 {media}%（CPM {chg_str(c['cpm_chg'])}）</span>
          <span><span class="dot" style="background:#a855f7"></span>创意侧 {creative}%（IPM {chg_str(c['ipm_chg'])}）</span>
        </div>
      </div>
    </div>
    <div class="metrics-grid">
      <div class="metric-pill"><div class="m-label">CPI</div><div class="m-val">{prev_cpi_text}→{curr_cpi_text}</div><div class="m-chg {chg_class(cpi_chg)}">{chg_str(cpi_chg)}</div></div>
      <div class="metric-pill"><div class="m-label">CPM</div><div class="m-val">{prev_cpm_text}→{curr_cpm_text}</div><div class="m-chg {chg_class(c.get('cpm_chg'))}">{chg_str(c.get('cpm_chg'))}</div></div>
      <div class="metric-pill"><div class="m-label">IPM</div><div class="m-val">{prev_ipm_text}→{curr_ipm_text}</div><div class="m-chg {chg_class(c.get('ipm_chg'))}">{chg_str(c.get('ipm_chg'))}</div></div>
      {ctr_row}
      <div class="metric-pill"><div class="m-label">花费</div><div class="m-val">${c['prev_spend']:,.0f}→${c['curr_spend']:,.0f}</div></div>
      <div class="metric-pill"><div class="m-label">BI DNU</div><div class="m-val">{c.get('prev_dnu', 0):,.0f}→{c.get('curr_dnu', 0):,.0f}</div></div>
      <div class="metric-pill"><div class="m-label">Moloco installs</div><div class="m-val">{c['prev_installs']:,}→{c['curr_installs']:,}</div></div>
    </div>
    {benchmark_html}
    <div class="table-section">
      {campaigns_html}
      {exchanges_html}
      {publishers_html}
      {formats_html}
    </div>
    <div class="conclusion"><strong>结论：</strong>{c['conclusion']}</div>
  </div>"""


def render_product_tab(prod):
    """Render tab content for one product."""
    key = prod["key"]
    os_label = prod["os"]
    os_cls = "os-ios" if os_label == "iOS" else "os-and"

    # no_data placeholder
    if prod.get("no_data"):
        return f"""
<div id="{key}" class="tab-content">
  <div class="product-header">
    <span class="product-id-badge">{prod['label']}</span>
    <span class="{os_cls} os-badge">{os_label}</span>
    <h2>{prod['name']} · {prod['product_id']}</h2>
    <span style="margin-left:auto;font-size:12px;background:#fef9c3;color:#854d0e;border:1px solid #fde68a;border-radius:20px;padding:2px 10px;">⏳ 数据待查</span>
  </div>
  <div style="padding:40px;text-align:center;color:#94a3b8;font-size:13px;">
    本产品数据将在下次周报更新时填入
  </div>
</div>"""

    # no_alert product (e.g. 1180 Android)
    if prod.get("no_alert"):
        incomplete = any(c.get("bi_data_complete") is False for c in prod.get("all_countries", []))
        status_text = "部分BI数据不完整，暂不判断这些国家是否触发" if incomplete else "完整可比数据中，无CPI或DNU涨跌幅达到10%的国家"
        rows = ""
        for c in prod.get("all_countries", []):
            cpi_chg = c.get("cpi_chg")
            if cpi_chg is None:
                cls = "chg-flat"
                label = "新增" if c.get("prev_spend", 0) <= 0 and c.get("curr_spend", 0) > 0 else ("暂停" if c.get("curr_spend", 0) <= 0 else "—")
                badge_bg, badge_col, badge_border = "#f8fafc", "#64748b", "#e2e8f0"
                badge = f'<span style="font-size:11px;padding:1px 6px;border-radius:10px;background:{badge_bg};color:{badge_col};border:1px solid {badge_border}">{label}</span>'
            else:
                cls = "chg-up" if cpi_chg > 0 else "chg-down"
                badge_bg = "#fef2f2" if cpi_chg > 0 else "#f0fdf4"
                badge_col = "#dc2626" if cpi_chg > 0 else "#16a34a"
                badge_border = "#fecaca" if cpi_chg > 0 else "#bbf7d0"
                badge = f'<span style="font-size:11px;padding:1px 6px;border-radius:10px;background:{badge_bg};color:{badge_col};border:1px solid {badge_border}">{chg_str(cpi_chg)}</span>'
            prev_cpi = f"${c['prev_cpi']:.2f}" if c.get("prev_cpi") is not None else "—"
            curr_cpi = f"${c['curr_cpi']:.2f}" if c.get("curr_cpi") is not None else "—"
            if c.get("prev_cpm") is not None and c.get("curr_cpm") is not None:
                cpm_v = c["curr_cpm"] - c["prev_cpm"]
                cpm_display = f"${c['prev_cpm']:.2f}→${c['curr_cpm']:.2f}"
            else:
                cpm_v = c.get("cpm_chg")
                cpm_display = chg_str(c.get("cpm_chg"))
            if c.get("prev_ipm") is not None and c.get("curr_ipm") is not None:
                ipm_v = c["curr_ipm"] - c["prev_ipm"]
                ipm_display = f"{c['prev_ipm']:.2f}→{c['curr_ipm']:.2f}"
            else:
                ipm_v = c.get("ipm_chg")
                ipm_display = chg_str(c.get("ipm_chg"))
            rows += f"""<tr>
              <td>{c['flag']} {c['name']}</td>
              <td>{prev_cpi}</td><td>{curr_cpi}</td>
              <td class="{cls}">{badge}</td>
              <td class="{chg_class(cpm_v)}">{cpm_display}</td>
              <td class="{chg_class(ipm_v)}">{ipm_display}</td>
            </tr>"""
        body = f"""
    <div style="padding:16px 20px 8px;">
      <div style="display:inline-block;background:#f8fafc;border:1px solid #e2e8f0;border-radius:8px;padding:4px 14px;font-size:12px;color:#475569;font-weight:600;margin-bottom:12px;">{status_text}</div>
    </div>
    <div style="padding:0 20px 16px;">
      <table>
        <tr><th>国家</th><th>CPI 上期</th><th>CPI 本期</th><th>CPI 变化</th><th>CPM</th><th>IPM</th></tr>
        {rows}
      </table>
    </div>"""
        alert_badge = '<span style="margin-left:auto;font-size:12px;color:#64748b;">' + ('BI待补齐' if incomplete else '无触发') + '</span>'
        return f"""
<div id="{key}" class="tab-content">
  <div class="product-header">
    <span class="product-id-badge">{prod['label']}</span>
    <span class="{os_cls} os-badge">{os_label}</span>
    <h2>{prod['name']} · {prod['product_id']}</h2>
    {alert_badge}
  </div>
  {body}
</div>"""

    # normal product with countries
    countries = prod.get("countries", [])
    alert_countries = [c for c in countries if is_country_triggered(c)]
    up_count = sum(1 for c in alert_countries if (c.get("cpi_chg") or 0) > 0)
    down_count = sum(1 for c in alert_countries if (c.get("cpi_chg") or 0) < 0)
    dnu_only_count = sum(1 for c in alert_countries if c.get("cpi_chg") is None or abs(c.get("cpi_chg") or 0) < 10)
    cnt = len(alert_countries)
    body = "".join(render_country_block(c) for c in countries)

    if cnt == 0:
        alert_badge = f'<span style="margin-left:auto;font-size:12px;background:#f0fdf4;color:#16a34a;border:1px solid #bbf7d0;border-radius:20px;padding:2px 10px;">✓ 无预警</span>'
    else:
        parts = []
        if up_count: parts.append(f'<span style="color:#dc2626">↑{up_count}</span>')
        if down_count: parts.append(f'<span style="color:#16a34a">↓{down_count}</span>')
        if dnu_only_count: parts.append(f'<span style="color:#d97706">DNU {dnu_only_count}</span>')
        inner = " ".join(parts)
        alert_badge = f'<span class="alert-count">{inner} 国家预警</span>'

    return f"""
<div id="{key}" class="tab-content">
  <div class="product-header">
    <span class="product-id-badge">{prod['label']}</span>
    <span class="{os_cls} os-badge">{os_label}</span>
    <h2>{prod['name']} · {prod['product_id']}</h2>
    {alert_badge}
  </div>
  {body}
</div>"""


def make_tab_badge(prod):
    if prod.get("no_data"):
        return '<span class="badge pending">—</span>'
    if prod.get("no_alert"):
        if any(c.get("bi_data_complete") is False for c in prod.get("all_countries", [])):
            return '<span class="badge pending">BI待补齐</span>'
        return '<span class="badge ok">✓</span>'
    countries = prod.get("countries", [])
    cnt = sum(1 for c in countries if is_country_triggered(c))
    up = sum(1 for c in countries if c.get("cpi_chg") is not None and c["cpi_chg"] >= 10)
    down = sum(1 for c in countries if c.get("cpi_chg") is not None and c["cpi_chg"] <= -10)
    dnu_only = sum(1 for c in countries if is_country_triggered(c) and (c.get("cpi_chg") is None or abs(c.get("cpi_chg") or 0) < 10))
    if cnt == 0:
        return '<span class="badge ok">✓</span>'
    parts = []
    if up:   parts.append(f'<span style="color:#fecaca">↑{up}</span>')
    if down: parts.append(f'<span style="color:#bbf7d0">↓{down}</span>')
    if dnu_only: parts.append(f'<span style="color:#fde68a">DNU {dnu_only}</span>')
    return f'<span class="badge">{" ".join(parts)}</span>'


def html_escape(v):
    return str(v if v is not None else "").replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;")


def summary_period_label(period):
    parts = [p.strip() for p in period.split("~")]
    if len(parts) != 2:
        return period
    start, end = parts
    if len(start) == 10 and len(end) == 10 and start[:5] == end[:5]:
        end = end[5:]
    return f"{start} ~ {end}"


def fmt_summary_pct(v):
    if v is None:
        return "—"
    return chg_str(v)


def country_dnu_chg(c):
    if c.get("prev_dnu") is None or c.get("curr_dnu") is None:
        return None
    prev_v = c.get("prev_dnu", 0) or 0
    curr_v = c.get("curr_dnu", 0) or 0
    if prev_v <= 0:
        return None
    return (curr_v / prev_v - 1) * 100


def summary_country_rows(prod):
    countries = prod.get("all_countries") or prod.get("countries", [])
    rows = []
    for c in countries:
        cpi_chg = c.get("cpi_chg")
        dnu_chg = country_dnu_chg(c)
        cpi_trigger = cpi_chg is not None and abs(cpi_chg) >= 10
        dnu_trigger = dnu_chg is not None and abs(dnu_chg) >= 10
        if not cpi_trigger and not dnu_trigger:
            continue
        if max(c.get("prev_dnu", 0) or 0, c.get("curr_dnu", 0) or 0) < 50:
            continue
        rows.append(c)
    return rows


def summary_driver(c):
    if c.get("metric_divergence"):
        return "DNU/归因口径"
    cpi_chg = c.get("cpi_chg") or 0
    cpm = c.get("cpm_chg") or 0
    ctr = c.get("ctr_chg") or 0
    i2c = c.get("cvr_chg") if c.get("cvr_chg") is not None else c.get("ipm_chg")
    i2c = i2c or 0
    if cpi_chg >= 0:
        candidates = [("CPM", cpm), ("CTR", -ctr), ("I2C", -i2c)]
    else:
        candidates = [("CPM", -cpm), ("CTR", ctr), ("I2C", i2c)]
    return max(candidates, key=lambda x: x[1])[0]


def validate_weekly_summary_consistency(d):
    """Ensure summary metrics and narratives come from the same country snapshot."""
    errors = []
    cpi_pattern = re.compile(
        r"(?:BI blackswan_cpi|BI new_individual_attribution_cpi|Moloco Spend / BI DNU) "
        r"CPI(上涨|下降)\s*([0-9.]+)%"
    )
    dnu_pattern = re.compile(r"本周DNU(上涨|下降)\s*([0-9.]+)%")

    def close_enough(left, right, tolerance=0.11):
        if left is None or right is None:
            return left is None and right is None
        return abs(float(left) - float(right)) <= tolerance

    for acc in d["accounts"]:
        for prod in acc["products"]:
            details = {c.get("code"): c for c in prod.get("countries", [])}
            expected_codes = {c.get("code") for c in summary_country_rows(prod)}
            actual_codes = set(details)
            if expected_codes != actual_codes:
                errors.append(
                    f"{prod['key']}: 触发国家不一致，首页={sorted(expected_codes)} 详情={sorted(actual_codes)}"
                )
            for summary_country in summary_country_rows(prod):
                code = summary_country.get("code")
                detail = details.get(code)
                scope = f"{prod['key']} · {code}"
                if detail is None:
                    errors.append(f"{scope}: 首页触发国家缺少详情数据")
                    continue

                for field in ("cpi_chg", "prev_cpi", "curr_cpi", "prev_dnu", "curr_dnu"):
                    if not close_enough(summary_country.get(field), detail.get(field)):
                        errors.append(
                            f"{scope}: {field} 首页={summary_country.get(field)} 详情={detail.get(field)}"
                        )

                prev_cpi = detail.get("prev_cpi")
                curr_cpi = detail.get("curr_cpi")
                expected_cpi_chg = (
                    (float(curr_cpi) / float(prev_cpi) - 1) * 100
                    if prev_cpi not in (None, 0) and curr_cpi is not None
                    else None
                )
                if not close_enough(detail.get("cpi_chg"), expected_cpi_chg):
                    errors.append(
                        f"{scope}: CPI涨跌幅={detail.get('cpi_chg')} 与上期/本期CPI不一致"
                    )

                expected_prev_moloco = (
                    float(detail["prev_spend"]) / float(detail["prev_installs"])
                    if detail.get("prev_installs") else None
                )
                expected_curr_moloco = (
                    float(detail["curr_spend"]) / float(detail["curr_installs"])
                    if detail.get("curr_installs") else None
                )
                if not close_enough(detail.get("prev_moloco_cpi"), expected_prev_moloco):
                    errors.append(f"{scope}: 上期Moloco CPI与消耗/installs不一致")
                if not close_enough(detail.get("curr_moloco_cpi"), expected_curr_moloco):
                    errors.append(f"{scope}: 本期Moloco CPI与消耗/installs不一致")

                if detail.get("cpi_source") == "Moloco Spend / BI DNU":
                    expected_prev_bi = (
                        float(detail["prev_spend"]) / float(detail["prev_dnu"])
                        if detail.get("prev_dnu") else None
                    )
                    expected_curr_bi = (
                        float(detail["curr_spend"]) / float(detail["curr_dnu"])
                        if detail.get("curr_dnu") else None
                    )
                    if not close_enough(prev_cpi, expected_prev_bi):
                        errors.append(f"{scope}: 回退口径上期CPI与Moloco消耗/BI DNU不一致")
                    if not close_enough(curr_cpi, expected_curr_bi):
                        errors.append(f"{scope}: 回退口径本期CPI与Moloco消耗/BI DNU不一致")

                for market in detail.get("market_benchmarks", []):
                    if detail.get("moloco_cpi_chg") is None or market.get("cpi_chg") is None:
                        continue
                    expected_gap = detail["moloco_cpi_chg"] - market["cpi_chg"]
                    if not close_enough(market.get("customer_vs_market_cpi_chg"), expected_gap):
                        errors.append(f"{scope}: 客户相对大盘差值未使用Moloco同口径")

                conclusion = detail.get("conclusion", "")
                cpi_match = cpi_pattern.search(conclusion)
                cpi_chg = detail.get("cpi_chg")
                if cpi_chg is not None and abs(cpi_chg) >= 10:
                    if not cpi_match:
                        errors.append(f"{scope}: 归因结论缺少国家CPI涨跌幅")
                    else:
                        narrative_cpi = float(cpi_match.group(2)) * (
                            1 if cpi_match.group(1) == "上涨" else -1
                        )
                        if not close_enough(cpi_chg, narrative_cpi):
                            errors.append(
                                f"{scope}: CPI指标={cpi_chg:.1f}% 结论={narrative_cpi:.1f}%"
                            )
                    if "Moloco installs CPI" not in conclusion:
                        errors.append(f"{scope}: 归因结论缺少Moloco明细口径")

                dnu_match = dnu_pattern.search(conclusion)
                dnu_chg = country_dnu_chg(detail)
                if dnu_chg is not None and abs(dnu_chg) >= 10:
                    if not dnu_match:
                        errors.append(f"{scope}: 归因结论缺少DNU涨跌幅")
                    else:
                        narrative_dnu = float(dnu_match.group(2)) * (
                            1 if dnu_match.group(1) == "上涨" else -1
                        )
                        if not close_enough(dnu_chg, narrative_dnu):
                            errors.append(
                                f"{scope}: DNU指标={dnu_chg:.1f}% 结论={narrative_dnu:.1f}%"
                            )

    if errors:
        raise ValueError("周报首页数据一致性校验失败:\n- " + "\n- ".join(errors))
    print("✓ 周报首页指标与归因结论一致性校验通过")


def render_weekly_summary(d):
    red_total = yellow_total = segment_total = 0
    blocks = ""

    for acc in d["accounts"]:
        for prod in acc["products"]:
            rows_data = summary_country_rows(prod)
            detail_by_code = {c.get("code"): c for c in prod.get("countries", [])}
            all_segments = prod.get("all_countries") or prod.get("countries", [])
            segment_total += sum(
                1 for c in all_segments
                if max(c.get("prev_dnu", 0) or 0, c.get("curr_dnu", 0) or 0) >= 50
            )
            if not rows_data:
                continue

            red_count = sum(
                1 for c in rows_data
                if max(abs(c.get("cpi_chg") or 0), abs(country_dnu_chg(c) or 0)) >= 15
            )
            yellow_count = sum(
                1 for c in rows_data
                if 10 <= max(abs(c.get("cpi_chg") or 0), abs(country_dnu_chg(c) or 0)) < 15
            )
            red_total += red_count
            yellow_total += yellow_count

            rows = ""
            for c in rows_data:
                detail = detail_by_code.get(c.get("code"), c)
                cpi_chg = c.get("cpi_chg") or 0
                dnu_chg = country_dnu_chg(c)
                trigger_parts = []
                if abs(cpi_chg) >= 10:
                    trigger_parts.append("CPI")
                if dnu_chg is not None and abs(dnu_chg) >= 10:
                    trigger_parts.append("DNU")
                trigger_label = " & ".join(trigger_parts) or "—"
                red = max(abs(cpi_chg), abs(dnu_chg or 0)) >= 15
                flag = "🔴" if red else "🟡"
                direction = "up" if cpi_chg > 0 else "down"
                cpi_cls = f"cpi-{direction}-strong" if red else f"cpi-{direction}"
                os_cls = "os-ios" if prod["os"] == "iOS" else "os-android"
                curr_cpi = c.get("curr_cpi")
                curr_cpi_s = f"${curr_cpi:.2f}" if curr_cpi is not None else "—"
                i2c_chg = c.get("cvr_chg") if c.get("cvr_chg") is not None else c.get("ipm_chg")
                rows += f"""
        <tr>
          <td>{flag}</td>
          <td>{html_escape(c.get('code') or c.get('name'))}</td>
          <td><span class="os-badge {os_cls}">{html_escape(prod['os']).upper()}</span></td>
          <td>{html_escape(prod['label'].replace('US ', ''))}</td>
          <td>{trigger_label}</td>
          <td class="num {cpi_cls}">{chg_str(cpi_chg)}</td>
          <td class="num {chg_class(dnu_chg)}">{chg_str(dnu_chg)}</td>
          <td>{summary_driver(c)}</td>
          <td class="num">{fmt_summary_pct(c.get('cpm_chg'))}</td>
          <td class="num">{fmt_summary_pct(c.get('ctr_chg'))}</td>
          <td class="num">{fmt_summary_pct(i2c_chg)}</td>
          <td class="num">{curr_cpi_s}</td>
          <td class="summary-sentence">{html_escape(detail.get('conclusion', ''))}</td>
        </tr>"""

            product_label = prod.get("name") or prod["label"]
            blocks += f"""
    <div class="acct-block">
      <div class="acct-header">
        <span class="acct-label">{html_escape(product_label)}</span>
        <span class="acct-id">{html_escape(prod['product_id'])}</span>
        <span class="acct-summary"><span class="acct-red">🔴 {red_count}</span> · <span class="acct-yellow">🟡 {yellow_count}</span> · 共 {len(rows_data)} 个触发（{len(all_segments)} 个 segment）</span>
      </div>
      <table class="seg-table">
        <thead><tr>
          <th>Flag</th><th>国家</th><th>OS</th><th>App</th>
          <th>触发</th><th class="num">CPI Δ</th><th class="num">DNU Δ</th><th>主导</th>
          <th class="num">CPM</th><th class="num">CTR</th><th class="num">I2C</th>
          <th class="num">当前 CPI</th><th>一句话归因</th>
        </tr></thead>
        <tbody>{rows}
        </tbody>
      </table>
    </div>"""

    if not blocks:
        blocks = """
    <div class="acct-block">
      <div class="acct-header">
        <span class="acct-label">本周期无触发 segment</span>
        <span class="acct-summary"><span class="acct-green">整体表现稳定</span></span>
      </div>
    </div>"""

    product_count = sum(len(acc["products"]) for acc in d["accounts"])

    return f"""
<!-- ========================================================== -->
<!-- TT 周报 · 多账户总结报告（generated by report template） -->
<!-- ========================================================== -->
<section class="weekly-summary">
  <style scoped>
    .weekly-summary {{ font-family: -apple-system, 'PingFang SC', sans-serif; background: white; border-radius: 12px; padding: 22px 28px; margin-bottom: 16px; }}
    .weekly-summary h2 {{ font-size: 18px; font-weight: 700; border-bottom: 2px solid #6366f1; padding-bottom: 8px; margin-bottom: 16px; color: #1e293b; }}
    .weekly-summary .scope {{ background:#eff6ff; border-left:4px solid #3b82f6; padding:10px 14px; margin-bottom:14px; border-radius:4px; font-size:12px; color:#334155; }}
    .weekly-summary .scope strong {{ color: #1e40af; }}
    .weekly-summary .system-obs {{ background:#fef3c7; border-left:4px solid #f59e0b; padding:12px 16px; margin-bottom:18px; border-radius:4px; font-size:13px; }}
    .weekly-summary .summary-stats {{ display:flex; gap: 16px; margin-bottom: 16px; }}
    .weekly-summary .stat-card {{ flex: 1; padding: 12px 16px; border-radius: 8px; background: #f8fafc; border: 1px solid #e2e8f0; }}
    .weekly-summary .stat-card .label {{ font-size: 11px; color: #64748b; text-transform: uppercase; letter-spacing: 0.5px; }}
    .weekly-summary .stat-card .value {{ font-size: 22px; font-weight: 700; margin-top: 4px; }}
    .weekly-summary .stat-red {{ color: #dc2626; }}
    .weekly-summary .stat-yellow {{ color: #d97706; }}
    .weekly-summary .stat-green {{ color: #059669; }}
    .weekly-summary .acct-block {{ margin-bottom: 18px; padding: 12px 14px; background: #f8fafc; border-radius: 8px; }}
    .weekly-summary .acct-header {{ display: flex; align-items: center; gap: 10px; margin-bottom: 10px; padding-bottom: 8px; border-bottom: 1px solid #e2e8f0; }}
    .weekly-summary .acct-label {{ font-weight: 700; font-size: 14px; color: #1e293b; }}
    .weekly-summary .acct-id {{ font-family: monospace; font-size: 11px; color: #94a3b8; padding: 2px 6px; background: #e2e8f0; border-radius: 3px; }}
    .weekly-summary .acct-summary {{ margin-left: auto; font-size: 12px; color: #64748b; }}
    .weekly-summary .acct-red {{ color: #dc2626; font-weight: 600; }}
    .weekly-summary .acct-yellow {{ color: #d97706; font-weight: 600; }}
    .weekly-summary .acct-green {{ color: #059669; font-weight: 500; }}
    .weekly-summary .seg-table {{ width: 100%; border-collapse: collapse; font-size: 12px; }}
    .weekly-summary .seg-table th {{ padding: 7px 8px; background: white; border: 1px solid #e2e8f0; text-align: left; font-weight: 600; color: #475569; }}
    .weekly-summary .seg-table td {{ padding: 7px 8px; border: 1px solid #e2e8f0; }}
    .weekly-summary .seg-table .summary-sentence {{ min-width:420px; max-width:620px; white-space:normal; line-height:1.55; color:#334155; }}
    .weekly-summary .seg-table .num {{ text-align: right; font-variant-numeric: tabular-nums; }}
    .weekly-summary .cpi-up {{ color: #d97706; font-weight: 600; }}
    .weekly-summary .cpi-up-strong {{ color: #dc2626; font-weight: 700; }}
    .weekly-summary .cpi-down {{ color: #059669; font-weight: 600; }}
    .weekly-summary .cpi-down-strong {{ color: #047857; font-weight: 700; }}
    .weekly-summary .os-badge {{ display: inline-block; padding: 1px 6px; border-radius: 3px; font-size: 10px; font-weight: 600; }}
    .weekly-summary .os-android {{ background: #d1fae5; color: #065f46; }}
    .weekly-summary .os-ios {{ background: #dbeafe; color: #1e3a8a; }}
    .weekly-summary .footer {{ margin-top: 14px; padding-top: 10px; border-top: 1px solid #e2e8f0; font-size: 11px; color: #64748b; }}
  </style>

  <h2>📋 周报总结 · CPI 归因 (本期 {summary_period_label(d['period_curr'])})</h2>

  <div class="scope">
    <strong>📌 报告范围</strong> · BI CPI或DNU涨跌幅达到10%触发归因，任一期BI DNU至少50；消耗变化用于解释量级，不等同于预算设置变化。预算与屏蔽调整建议需结合客户目标评估。
  </div>

  <div class="system-obs">
    <strong>⚠️ 口径说明</strong>: 国家BI CPI与Moloco installs CPI分别展示；两者走势明显分化时，媒体、事件明细不能直接证明BI成本变化的原因。
  </div>

  <div class="summary-stats">
    <div class="stat-card"><div class="label">触发 🔴 RED (≥15%)</div><div class="value stat-red">{red_total}</div></div>
    <div class="stat-card"><div class="label">触发 🟡 YELLOW (≥10%)</div><div class="value stat-yellow">{yellow_total}</div></div>
    <div class="stat-card"><div class="label">分析 segments 总数</div><div class="value">{segment_total}</div></div>
    <div class="stat-card"><div class="label">产品数（含OS）</div><div class="value">{product_count}</div></div>
  </div>

{blocks}

  <div class="footer">
    触发阈值: CPI 或 DNU ±10% 🟡 / ±15% 🔴 (客户对齐, 无 σ 校准) · Segment 量级地板 ≥50 BI DNU/周（任一期）<br>
    Segment 维度: 账户 × 国家 × OS × App (1180/1233/1340) · CPI/DNU: <code>sandbox BI</code> · 归因明细: <code>Moloco fact_dsp_core</code>
  </div>
</section>"""


def render_pine_drama_tab(pine):
    countries = pine.get("countries", []) if pine else []
    if not countries:
        return """
<div id="pine_drama" class="tab-content">
  <div class="product-header"><span class="product-id-badge">PINE</span><h2>PineDrama投放表现</h2></div>
  <div style="padding:40px;text-align:center;color:#94a3b8;">本周期没有campaign name含pinereuse或pine_test的投放数据</div>
</div>"""

    overview_rows = ""
    for c in countries:
        pine_dnu = f"{c['pine_dnu']:,.0f}" if c.get("pine_dnu") is not None else "—"
        country_dnu = f"{c['country_dnu']:,.0f}" if c.get("country_dnu") is not None else "—"
        dnu_share = f"{c['pine_dnu_share']:.1f}%" if c.get("pine_dnu_share") is not None else "—"
        curr_pine_cpi = f"${c['curr_pine_cpi']:.2f}" if c.get("curr_pine_cpi") is not None else "—"
        country_avg = f"${c['country_avg_cpi']:.2f}" if c.get("country_avg_cpi") is not None else "—"
        pine_source = html_escape(c.get("pine_cpi_source", "—"))
        country_source = html_escape(c.get("country_cpi_source", "—"))
        overall_recommendation = html_escape(c.get("recommendation", "—"))
        overview_rows += f"""
        <tr>
          <td>{html_escape(c['country'])}</td><td>{html_escape(c['app_code'])}</td><td>{html_escape(c['os'])}</td>
          <td class="num">{pine_dnu}</td><td class="num">{country_dnu}</td><td class="num">{dnu_share}</td>
          <td class="num">${c.get('curr_pine_spend', 0):,.0f}</td><td class="num">{curr_pine_cpi}<small class="pine-source">{pine_source}</small></td>
          <td class="num {chg_class(c.get('pine_cpi_chg'))}">{chg_str(c.get('pine_cpi_chg'))}</td><td class="num">{country_avg}<small class="pine-source">{country_source}</small></td>
          <td class="pine-action">{overall_recommendation}</td>
        </tr>"""

    campaign_sections = ""
    for c in countries:
        campaigns = c.get("campaigns", [])
        if not campaigns:
            continue
        country_cpi = f"${c['country_avg_cpi']:.2f}" if c.get("country_avg_cpi") is not None else "—"
        grouped = {
            pine_type: [row for row in campaigns if row.get("pine_type") == pine_type]
            for pine_type in ("Pine Test", "Pine Reuse")
        }
        group_tables = ""
        for pine_type in ("Pine Test", "Pine Reuse"):
            rows = grouped[pine_type]
            if not rows:
                continue
            detail_rows = ""
            for row in rows:
                curr_cpi = f"${row['curr_cpi']:.2f}" if row.get("curr_cpi") is not None else "—"
                row_country_cpi = f"${row['country_cpi']:.2f}" if row.get("country_cpi") is not None else "—"
                curr_dnu = f"{row['curr_dnu']:,.0f}" if row.get("curr_dnu") is not None else "—"
                detail_rows += f"""
                <tr>
                  <td class="pine-campaign-name">{html_escape(row['campaign_name'])}</td>
                  <td class="num">${row.get('curr_spend', 0):,.0f}</td>
                  <td class="num">{curr_dnu}</td>
                  <td class="num">{curr_cpi}</td>
                  <td class="num {chg_class(row.get('cpi_chg'))}">{chg_str(row.get('cpi_chg'))}</td>
                  <td class="num">{row_country_cpi}</td>
                  <td><span class="pine-source-badge">{html_escape(row.get('cpi_source', '—'))}</span></td>
                  <td class="pine-action">{html_escape(row.get('recommendation', '保持观察'))}</td>
                </tr>"""
            type_class = "test" if pine_type == "Pine Test" else "reuse"
            group_tables += f"""
            <div class="pine-type-block">
              <div class="pine-type-title {type_class}">{pine_type}</div>
              <table class="pine-campaign-table">
                <tr><th>Campaign</th><th>本期消耗</th><th>BI DNU</th><th>Pine BI CPI</th><th>Pine CPI环比</th><th>国家整体BI CPI</th><th>CPI来源</th><th>建议</th></tr>
                {detail_rows}
              </table>
            </div>"""
        campaign_sections += f"""
        <section class="pine-country-detail">
          <div class="pine-country-title"><strong>{html_escape(c['country'])} / {html_escape(c['app_code'])} / {html_escape(c['os'])}</strong><span>国家整体BI CPI {country_cpi}</span></div>
          {group_tables}
        </section>"""

    return f"""
<div id="pine_drama" class="tab-content">
  <style scoped>
    .pine-wrap {{ padding:18px 20px 28px; }}
    .pine-note {{ background:#eff6ff;border-left:4px solid #2563eb;padding:10px 14px;margin-bottom:16px;color:#334155;line-height:1.5; }}
    .pine-overview {{ margin-bottom:20px; }}
    .pine-overview .num {{ text-align:right;font-variant-numeric:tabular-nums; }}
    .pine-country-detail {{ border-top:1px solid #e2e8f0;padding:15px 0 5px; }}
    .pine-country-title {{ display:flex;justify-content:space-between;gap:12px;align-items:center;margin-bottom:10px;color:#334155;font-size:13px; }}
    .pine-country-title span {{ color:#64748b;font-size:11px;white-space:nowrap; }}
    .pine-type-block {{ margin:9px 0 14px; }}
    .pine-type-title {{ display:inline-block;border-radius:4px;padding:3px 7px;font-size:10px;font-weight:800;margin-bottom:6px; }}
    .pine-type-title.test {{ background:#fff7ed;color:#c2410c; }}
    .pine-type-title.reuse {{ background:#ecfdf5;color:#047857; }}
    .pine-campaign-table {{ table-layout:fixed;width:100%; }}
    .pine-campaign-table th:first-child,.pine-campaign-table td:first-child {{ width:40%; }}
    .pine-campaign-table th:last-child,.pine-campaign-table td:last-child {{ width:20%; }}
    .pine-campaign-name {{ overflow-wrap:anywhere;line-height:1.45; }}
    .pine-action {{ white-space:normal;line-height:1.45;color:#334155; }}
    .pine-source {{ display:block;color:#94a3b8;font-size:9px;font-weight:500;margin-top:2px; }}
    .pine-source-badge {{ display:inline-block;background:#f1f5f9;color:#475569;border-radius:4px;padding:2px 5px;font-size:9px;white-space:nowrap; }}
    @media(max-width:680px) {{ .pine-overview {{ display:block;overflow-x:auto; }} }}
  </style>
  <div class="product-header">
    <span class="product-id-badge">PINE</span><h2>PineDrama投放表现</h2>
    <span style="margin-left:auto;font-size:12px;color:#64748b;">Pine专项（pinereuse + pine_test）</span>
  </div>
  <div class="pine-wrap">
    <div class="pine-note">国家Pine整体 = 该国家全部Pine Test campaign + 全部Pine Reuse campaign：Pine消耗与Pine BI DNU分别直接求和，Pine BI CPI按BI DNU汇总。国家整体BI CPI和国家BI DNU统计该国家、App、OS下的全部Moloco campaign，不限制Pine。Pine DNU占比 = Pine BI DNU ÷ 国家全部campaign BI DNU；BI CPI缺失时使用Moloco Spend ÷ BI DNU，BI DNU也缺失则留空。</div>
    <div class="table-title"><span class="icon icon-bench">D</span>国家整体与Pine专项表现</div>
    <table class="pine-overview">
      <tr><th>国家</th><th>App</th><th>OS</th><th>Pine BI DNU（仅Pine）</th><th>国家BI DNU（全部campaign）</th><th>Pine DNU占比</th>
          <th>Pine消耗（仅Pine）</th><th>Pine BI CPI</th><th>Pine CPI周环比</th><th>国家整体BI CPI</th><th>整体判断</th></tr>
      {overview_rows}
    </table>
    <div class="table-title" style="margin-top:24px;"><span class="icon icon-campaign">C</span>分Campaign表现与建议</div>
    {campaign_sections}
  </div>
</div>"""


def generate_html(d):
    pc = d["period_curr"]
    pp = d["period_prev"]
    accounts = d["accounts"]

    # Flatten all products for tab content rendering
    all_products = [p for acc in accounts for p in acc["products"]]
    fallback_count = sum(c.get("cpi_source") == "Moloco Spend / BI DNU"
                         for p in all_products for c in p.get("all_countries", []))
    incomplete_segments = [f"{p['label']} / {p['os']} / {c['code']}"
                           for p in all_products for c in p.get("all_countries", [])
                           if c.get("bi_data_complete") is False]
    coverage_note = f"<div class='meta'>本期有 {fallback_count} 个国家×产品×OS 使用 Moloco消耗 ÷ BI DNU，两个对比周期采用相同口径。</div>"
    if incomplete_segments:
        coverage_note += (f"<details class='meta'><summary>BI周期不完整：{len(incomplete_segments)} 个分组，暂不作完整周归因（不代表无波动）</summary>"
                          + html_escape("；".join(incomplete_segments)) + "</details>")

    # Build tab groups HTML
    tab_groups_html = ""
    for acc in accounts:
        btns = ""
        first_key = acc["products"][0]["key"] if acc["products"] else ""
        for prod in acc["products"]:
            os_cls = "os-ios" if prod["os"] == "iOS" else "os-and"
            badge = make_tab_badge(prod)
            btns += f'<button class="tab-btn" id="btn-{prod["key"]}" onclick="switchTab(\'{prod["key"]}\')">{prod["label"]} <span class="{os_cls} os-badge-sm">{prod["os"]}</span> {badge}</button>\n'
        tab_groups_html += f"""
    <div class="tab-group">
      <div class="tab-group-label">{acc['label']} <span class="acc-id">{acc['id']}</span></div>
      <div class="tab-btns">{btns}</div>
    </div>"""

    pine = d.get("pine_drama")
    if pine:
        tab_groups_html += f"""
    <div class="tab-group">
      <div class="tab-group-label">Pine专项</div>
      <div class="tab-btns"><button class="tab-btn" id="btn-pine_drama" onclick="switchTab('pine_drama')">PineDrama投放表现 <span class="badge ok">{len(pine.get('countries', []))}</span></button></div>
    </div>"""

    # Tab contents
    tab_contents = "\n".join(render_product_tab(p) for p in all_products)
    if pine:
        tab_contents += "\n" + render_pine_drama_tab(pine)
    weekly_summary_html = render_weekly_summary(d)

    # First tab key for JS init
    first_key = all_products[0]["key"] if all_products else ""

    # All keys for JS
    all_keys = [p["key"] for p in all_products]
    if pine:
        all_keys.append("pine_drama")
    all_keys_js = "[" + ",".join(f"'{key}'" for key in all_keys) + "]"

    return f"""<!DOCTYPE html>
<html lang="zh-CN">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>TikTok 投放数据归因 | {pc}</title>
<style>
  * {{ box-sizing: border-box; margin: 0; padding: 0; }}
  body {{ font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif; font-size: 13px; background: #f4f6f9; color: #1a1a2e; }}
  .page {{ max-width: 1280px; margin: 0 auto; padding: 20px; }}

  /* Password gate */
  #pw-gate {{
    position: fixed; inset: 0; z-index: 9999;
    background: linear-gradient(135deg, #1a1a2e 0%, #16213e 100%);
    display: flex; align-items: center; justify-content: center;
  }}
  #pw-box {{
    background: white; border-radius: 16px; padding: 36px 40px; width: 320px;
    box-shadow: 0 20px 60px rgba(0,0,0,0.5); text-align: center;
  }}
  #pw-box .lock {{ font-size: 36px; margin-bottom: 12px; }}
  #pw-box h2 {{ font-size: 16px; font-weight: 700; color: #1e293b; margin-bottom: 4px; }}
  #pw-box p {{ font-size: 12px; color: #94a3b8; margin-bottom: 20px; }}
  #pw-input {{
    width: 100%; padding: 11px 14px; border: 1.5px solid #e2e8f0; border-radius: 8px;
    font-size: 15px; letter-spacing: 4px; text-align: center; outline: none;
    transition: border-color 0.2s;
  }}
  #pw-input:focus {{ border-color: #6366f1; }}
  #pw-input.error {{ border-color: #ef4444; animation: shake 0.3s; }}
  #pw-err {{ font-size: 12px; color: #ef4444; margin-top: 8px; min-height: 16px; }}
  #pw-btn {{
    margin-top: 16px; width: 100%; padding: 11px; background: #6366f1;
    color: white; border: none; border-radius: 8px; font-size: 14px;
    font-weight: 600; cursor: pointer; transition: background 0.2s;
  }}
  #pw-btn:hover {{ background: #4f46e5; }}
  @keyframes shake {{
    0%,100% {{ transform: translateX(0); }}
    25% {{ transform: translateX(-6px); }}
    75% {{ transform: translateX(6px); }}
  }}

  .report-header {{ background: linear-gradient(135deg, #1a1a2e 0%, #16213e 100%); color: white; border-radius: 12px; padding: 22px 28px; margin-bottom: 16px; }}
  .report-header h1 {{ font-size: 20px; font-weight: 700; }}
  .report-header .period {{ margin-top: 8px; font-size: 13px; opacity: 0.9; }}
  .report-header .period .curr {{ background: rgba(255,255,255,0.15); border-radius: 6px; padding: 3px 10px; margin-right: 8px; }}
  .report-header .period .prev {{ opacity: 0.6; font-size: 12px; }}
  .report-header .meta {{ margin-top: 8px; font-size: 11px; opacity: 0.55; }}

  /* Tab groups */
  .tab-groups {{ display: flex; flex-direction: column; gap: 0; margin-bottom: 0; }}
  .tab-group {{ display: flex; align-items: center; gap: 4px; flex-wrap: wrap; background: #f8fafc; border: 1px solid #e2e8f0; border-bottom: none; border-radius: 10px 10px 0 0; padding: 8px 12px 0; }}
  .tab-group:not(:first-child) {{ border-top: none; border-radius: 0; }}
  .tab-group-label {{ font-size: 10px; font-weight: 700; color: #94a3b8; text-transform: uppercase; letter-spacing: 0.5px; white-space: nowrap; padding: 0 6px 8px 0; border-right: 1px solid #e2e8f0; margin-right: 4px; }}
  .acc-id {{ font-weight: 400; color: #cbd5e1; }}
  .tab-btns {{ display: flex; gap: 3px; flex-wrap: wrap; padding-bottom: 0; }}
  .tab-btn {{ padding: 6px 12px; border-radius: 6px 6px 0 0; border: 1px solid #e2e8f0; border-bottom: none; background: #f1f5f9; cursor: pointer; font-size: 12px; font-weight: 600; color: #64748b; transition: all 0.15s; display: flex; align-items: center; gap: 4px; margin-bottom: 0; }}
  .tab-btn:hover {{ background: #e8edf5; }}
  .tab-btn.active {{ background: white; color: #1e293b; border-color: #e2e8f0; position: relative; z-index: 1; }}
  .badge {{ display: inline-block; background: #ef4444; color: white; border-radius: 10px; padding: 1px 6px; font-size: 10px; }}
  .badge.ok {{ background: #22c55e; }}
  .badge.pending {{ background: #94a3b8; }}

  /* OS badges */
  .os-badge {{ border-radius: 4px; padding: 1px 5px; font-size: 10px; font-weight: 700; }}
  .os-badge-sm {{ border-radius: 3px; padding: 0px 4px; font-size: 9px; font-weight: 700; }}
  .os-and {{ background: #dcfce7; color: #15803d; }}
  .os-ios {{ background: #dbeafe; color: #1d4ed8; }}

  .tab-content {{ display: none; background: white; border-radius: 0 0 12px 12px; border: 1px solid #e2e8f0; overflow: hidden; box-shadow: 0 1px 4px rgba(0,0,0,0.06); }}
  .tab-content.active {{ display: block; }}

  .product-header {{ padding: 14px 20px; background: #f8fafc; border-bottom: 1px solid #e2e8f0; display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }}
  .product-id-badge {{ background: #1e293b; color: white; border-radius: 6px; padding: 3px 10px; font-size: 12px; font-weight: 700; }}
  .product-header h2 {{ font-size: 13px; font-weight: 600; color: #334155; }}
  .alert-count {{ margin-left: auto; font-size: 12px; background: #fef2f2; color: #dc2626; border: 1px solid #fecaca; border-radius: 20px; padding: 2px 10px; }}

  .country-block {{ border-bottom: 1px solid #f1f5f9; }}
  .country-block:last-child {{ border-bottom: none; }}
  .country-header {{ padding: 12px 20px; display: flex; align-items: center; gap: 10px; flex-wrap: wrap; }}
  .country-name {{ font-size: 14px; font-weight: 600; }}
  .cpi-badge {{ border-radius: 20px; padding: 3px 12px; font-size: 12px; font-weight: 700; }}
  .cpi-up {{ background: #fef2f2; color: #dc2626; border: 1px solid #fecaca; }}
  .cpi-down {{ background: #f0fdf4; color: #16a34a; border: 1px solid #bbf7d0; }}
  .attr-badge {{ border-radius: 20px; padding: 3px 10px; font-size: 11px; margin-left: 4px; }}
  .attr-media {{ background: #fff7ed; color: #ea580c; border: 1px solid #fed7aa; }}
  .attr-creative {{ background: #fdf4ff; color: #9333ea; border: 1px solid #e9d5ff; }}
  .attr-both {{ background: #eff6ff; color: #2563eb; border: 1px solid #bfdbfe; }}

  .attr-section {{ padding: 10px 20px 0; }}
  .attr-bar-wrap {{ display: flex; align-items: center; gap: 10px; margin-bottom: 10px; }}
  .attr-bar {{ flex: 1; height: 8px; background: #f1f5f9; border-radius: 4px; overflow: hidden; display: flex; }}
  .attr-media-fill {{ background: #f97316; height: 100%; }}
  .attr-creative-fill {{ background: #a855f7; height: 100%; }}
  .attr-labels {{ font-size: 11px; color: #64748b; white-space: nowrap; }}
  .attr-labels span {{ margin-right: 12px; }}
  .attr-labels .dot {{ display: inline-block; width: 8px; height: 8px; border-radius: 50%; margin-right: 3px; vertical-align: middle; }}

  .metrics-grid {{ display: flex; gap: 8px; padding: 0 20px 12px; flex-wrap: wrap; }}
  .metric-pill {{ background: #f8fafc; border: 1px solid #e2e8f0; border-radius: 8px; padding: 8px 12px; min-width: 100px; }}
  .metric-pill .m-label {{ font-size: 10px; color: #94a3b8; text-transform: uppercase; }}
  .metric-pill .m-val {{ font-size: 12px; font-weight: 600; margin: 2px 0; }}
  .metric-pill .m-chg {{ font-size: 11px; }}
  .chg-up {{ color: #dc2626; font-weight: 600; }}
  .chg-down {{ color: #16a34a; font-weight: 600; }}
  .chg-flat {{ color: #94a3b8; }}

  .table-section {{ padding: 0 20px 16px; }}
  .table-title {{ font-size: 11px; font-weight: 600; color: #475569; text-transform: uppercase; letter-spacing: 0.5px; margin: 12px 0 6px; display: flex; align-items: center; gap: 5px; }}
  .icon {{ width: 16px; height: 16px; border-radius: 4px; display: inline-flex; align-items: center; justify-content: center; font-size: 10px; font-weight: 700; flex-shrink: 0; }}
  .icon-media {{ background: #fff7ed; color: #ea580c; }}
  .icon-creative {{ background: #fdf4ff; color: #9333ea; }}
  .icon-pub {{ background: #eff6ff; color: #2563eb; }}
  .icon-fmt {{ background: #f0fdf4; color: #16a34a; }}
  .icon-bench {{ background: #fef3c7; color: #b45309; }}
  .benchmark-section {{ padding: 0 20px 4px; }}
  table {{ width: 100%; border-collapse: collapse; font-size: 12px; }}
  th {{ background: #f8fafc; color: #64748b; font-size: 11px; font-weight: 600; padding: 7px 10px; text-align: left; border-bottom: 1px solid #e2e8f0; white-space: nowrap; }}
  td {{ padding: 7px 10px; border-bottom: 1px solid #f1f5f9; white-space: nowrap; }}
  tr:last-child td {{ border-bottom: none; }}
  tr:hover td {{ background: #fafbfd; }}
  .name-cell {{ max-width: 220px; overflow: hidden; text-overflow: ellipsis; }}
  .share-up {{ color: #f97316; font-weight: 600; }}
  .share-down {{ color: #64748b; }}
  .tag {{ font-size: 10px; border-radius: 3px; padding: 1px 5px; }}
  .tag-warn {{ background: #fef2f2; color: #dc2626; border: 1px solid #fecaca; }}
  .tag-ok {{ background: #f0fdf4; color: #16a34a; border: 1px solid #bbf7d0; }}
  .fmt-badge {{ background: #f1f5f9; color: #334155; border: 1px solid #e2e8f0; border-radius: 4px; padding: 1px 6px; font-size: 11px; font-weight: 600; }}
  .pending-msg {{ background: #fafafa; border: 1px dashed #e2e8f0; border-radius: 8px; padding: 10px 14px; font-size: 12px; color: #94a3b8; margin: 8px 0; }}

  .conclusion {{ margin: 0 20px 16px; background: #f8fafc; border-left: 3px solid #6366f1; border-radius: 0 8px 8px 0; padding: 10px 14px; font-size: 12px; color: #334155; line-height: 1.6; }}
  .conclusion strong {{ color: #1e293b; }}

  .copy-btn {{ position: fixed; bottom: 24px; right: 24px; background: #6366f1; color: white; border: none; border-radius: 50px; padding: 11px 20px; font-size: 13px; font-weight: 600; cursor: pointer; box-shadow: 0 4px 14px rgba(99,102,241,0.4); z-index: 100; }}
  .copy-btn:hover {{ background: #4f46e5; }}
  @media print {{ .copy-btn {{ display: none; }} }}
</style>
</head>
<body>

<!-- Password gate -->
<div id="pw-gate">
  <div id="pw-box">
    <div class="lock">🔒</div>
    <h2>TikTok 投放数据归因</h2>
    <p>请输入访问密码</p>
    <input id="pw-input" type="password" placeholder="密码" autocomplete="off"
           onkeydown="if(event.key==='Enter')checkPw()">
    <div id="pw-err"></div>
    <button id="pw-btn" onclick="checkPw()">进入</button>
  </div>
</div>

<div class="page">

<div class="report-header">
  <h1>TikTok 投放数据归因周报</h1>
  <div class="period">
    <span class="curr">📅 本期：{pc}</span>
    <span class="prev">对比上期：{pp}</span>
  </div>
<div class="meta">筛选条件：BI CPI 或 DNU 涨跌幅 ≥10% · 主指标：sandbox BI CPI；BI CPI 延迟时使用 Moloco spend ÷ BI DNU · DNU：sandbox BI · 归因明细及非游大盘：Moloco BQ · 生成于 {d['generated_at']}</div>
{coverage_note}
</div>

{weekly_summary_html}

<div class="tab-groups">
{tab_groups_html}
</div>

{tab_contents}

</div>

<button class="copy-btn" onclick="copyText()">📋 复制摘要</button>

<script>
(function() {{
  if (sessionStorage.getItem('tt_auth') === '1') {{
    document.getElementById('pw-gate').style.display = 'none';
  }}
}})();

function checkPw() {{
  const val = document.getElementById('pw-input').value;
  if (val === 'TT') {{
    sessionStorage.setItem('tt_auth', '1');
    document.getElementById('pw-gate').style.display = 'none';
  }} else {{
    const inp = document.getElementById('pw-input');
    inp.classList.remove('error'); void inp.offsetWidth; inp.classList.add('error');
    document.getElementById('pw-err').textContent = '密码错误，请重试';
    inp.value = '';
  }}
}}

const ALL_KEYS = {all_keys_js};

function switchTab(id) {{
  ALL_KEYS.forEach(k => {{
    const el = document.getElementById(k);
    const btn = document.getElementById('btn-' + k);
    if (el) el.classList.remove('active');
    if (btn) btn.classList.remove('active');
  }});
  const el = document.getElementById(id);
  const btn = document.getElementById('btn-' + id);
  if (el) el.classList.add('active');
  if (btn) btn.classList.add('active');
}}

// Init first tab
switchTab('{first_key}');

function copyText() {{
  const active = document.querySelector('.tab-content.active');
  if (!active) return;
  const text = active.innerText.replace(/\\n{{3,}}/g, '\\n\\n');
  navigator.clipboard.writeText(text).then(() => {{
    const btn = document.querySelector('.copy-btn');
    btn.textContent = '✓ 已复制';
    btn.style.background = '#22c55e';
    setTimeout(() => {{ btn.textContent = '📋 复制摘要'; btn.style.background = '#6366f1'; }}, 2000);
  }});
}}
</script>
</body>
</html>"""


def validate_pine_consistency(data):
    """发布前校验Pine国家汇总与分campaign明细使用同一范围和BI口径。"""
    errors = []

    def close_enough(left, right, tolerance):
        return left is not None and right is not None and abs(float(left) - float(right)) <= tolerance

    def check_recommendation(scope, curr_cpi, prev_cpi, country_cpi, recommendation):
        text = recommendation or ""
        if curr_cpi is not None and country_cpi is not None:
            if curr_cpi <= country_cpi and "高于国家均值" in text:
                errors.append(f"{scope}: CPI低于国家均值，但结论写为高于国家均值")
            if curr_cpi > country_cpi and "低于国家均值" in text:
                errors.append(f"{scope}: CPI高于国家均值，但结论写为低于国家均值")
        if curr_cpi is not None and prev_cpi not in (None, 0):
            is_up = curr_cpi > prev_cpi
            if is_up and "未恶化" in text:
                errors.append(f"{scope}: CPI环比上涨，但结论写为未恶化")
            if not is_up and "环比上涨" in text:
                errors.append(f"{scope}: CPI环比未上涨，但结论写为环比上涨")

    countries = (data.get("pine_drama") or {}).get("countries", [])
    for country in countries:
        label = f"{country.get('country')}/{country.get('app_code')}/{country.get('os')}"
        campaigns = country.get("campaigns", [])
        if not campaigns:
            continue

        campaign_spend = sum(float(row.get("curr_spend") or 0) for row in campaigns)
        if not close_enough(country.get("curr_pine_spend"), campaign_spend, 0.05):
            errors.append(
                f"{label}: Pine消耗 {country.get('curr_pine_spend')} != 分campaign合计 {campaign_spend:.2f}"
            )

        curr_dnus = [row.get("curr_dnu") for row in campaigns]
        if country.get("pine_dnu") is not None and all(value is not None for value in curr_dnus):
            campaign_dnu = sum(float(value) for value in curr_dnus)
            if not close_enough(country.get("pine_dnu"), campaign_dnu, 0.1):
                errors.append(
                    f"{label}: Pine DNU {country.get('pine_dnu')} != 分campaign合计 {campaign_dnu:.0f}"
                )
            if campaign_dnu > 0 and all(row.get("curr_cpi") is not None for row in campaigns):
                weighted_cpi = sum(float(row["curr_cpi"]) * float(row["curr_dnu"]) for row in campaigns) / campaign_dnu
                if not close_enough(country.get("curr_pine_cpi"), weighted_cpi, 0.01):
                    errors.append(
                        f"{label}: Pine CPI {country.get('curr_pine_cpi')} != 分campaign BI DNU汇总 {weighted_cpi:.4f}"
                    )

        for campaign in campaigns:
            scope = f"{label} · {campaign.get('campaign_name')}"
            if not close_enough(campaign.get("country_cpi"), country.get("country_avg_cpi"), 0.01):
                errors.append(
                    f"{scope}: 引用国家CPI {campaign.get('country_cpi')} != 国家整体BI CPI {country.get('country_avg_cpi')}"
                )
            check_recommendation(
                scope,
                campaign.get("curr_cpi"),
                campaign.get("prev_cpi"),
                campaign.get("country_cpi"),
                campaign.get("recommendation"),
            )
        check_recommendation(
            f"{label} · Pine整体",
            country.get("curr_pine_cpi"),
            country.get("prev_pine_cpi"),
            country.get("country_avg_cpi"),
            country.get("recommendation"),
        )

    if errors:
        raise ValueError("Pine数据一致性校验失败:\n- " + "\n- ".join(errors))
    print(f"✓ Pine一致性校验通过: {len(countries)}个国家")


def main():
    validate_weekly_summary_consistency(REPORT_DATA)
    validate_pine_consistency(REPORT_DATA)
    html = generate_html(REPORT_DATA)
    with open(OUTPUT_FILE, "w", encoding="utf-8") as f:
        f.write(html)
    print(f"✓ 报告已生成: {OUTPUT_FILE}")

    repo = str(REPO_DIR)
    period = REPORT_DATA["period_curr"].replace(" ", "").replace("~", "-")
    msg = f"report: {period} CPI归因报告"
    subprocess.run(["git", "-C", repo, "add", "index.html", "generate_tt_report.py", "assets/pine"], check=True)
    r = subprocess.run(["git", "-C", repo, "commit", "-m", msg], capture_output=True, text=True)
    commit_output = (r.stdout or "") + (r.stderr or "")
    if "nothing to commit" in commit_output:
        print("✓ 无变更，无需推送")
    else:
        if r.returncode != 0:
            print(commit_output, end="")
            raise SystemExit(r.returncode)
        p = subprocess.run(["git", "-C", repo, "push", "--set-upstream", "origin", "main"], capture_output=True, text=True)
        if p.returncode != 0:
            print((p.stdout or "") + (p.stderr or ""), end="")
            raise SystemExit(p.returncode)
        print("✓ 已推送到 GitHub Pages")


if __name__ == "__main__":
    main()
